# Auto-create a Journal Entry when an Animal Event with an activity cost is submitted.
if not doc.custom_activity_cost or float(doc.custom_activity_cost) <= 0:
    pass
else:
    try:
        settings = frappe.get_doc("Livestock Settings")
        if not settings.custom_auto_create_journal_entry:
            pass
        else:
            company = settings.custom_default_company
            credit_account = settings.custom_default_credit_account
            if not company or not credit_account:
                frappe.msgprint("Livestock Settings: Company or Credit Account not set.", indicator="orange")
            else:
                asset_link = frappe.db.get_value("Animal", doc.animal, "asset_link")
                animal_herd = frappe.db.get_value("Animal", doc.animal, "current_herd")
                asset_data = None
                if asset_link:
                    asset_data = frappe.db.get_value("Asset", asset_link, ["asset_category", "company"], as_dict=True)
                if not asset_data or not asset_data.asset_category:
                    frappe.msgprint("Animal " + str(doc.animal) + " has no linked Asset Category; JE skipped.", indicator="orange")
                else:
                    je_company = asset_data.company or company
                    cat_account = frappe.db.get_value(
                        "Asset Category Account",
                        {"parent": asset_data.asset_category, "company_name": je_company},
                        ["fixed_asset_account", "depreciation_expense_account"],
                        as_dict=True,
                    )
                    if not cat_account:
                        frappe.msgprint("No account row for " + str(je_company) + " in Asset Category.", indicator="orange")
                    else:
                        expense_account = cat_account.fixed_asset_account
                        if not expense_account:
                            frappe.msgprint("No Fixed Asset Account set.", indicator="orange")
                        else:
                            cost_center = None
                            if animal_herd:
                                cost_center = frappe.db.get_value("Herds", animal_herd, "cost_center")
                            frappe.db.set_value("Animal Event", doc.name, "custom_expense_account", expense_account, update_modified=False)
                            if cost_center:
                                frappe.db.set_value("Animal Event", doc.name, "custom_cost_center", cost_center, update_modified=False)
                            je = frappe.get_doc({
                                "doctype": "Journal Entry",
                                "voucher_type": "Journal Entry",
                                "company": je_company,
                                "posting_date": doc.event_date or frappe.utils.today(),
                                "user_remark": "Auto: " + str(doc.event_type) + " - " + str(doc.animal) + " [" + str(doc.name) + "]",
                                "accounts": [
                                    {"account": expense_account, "debit_in_account_currency": float(doc.custom_activity_cost), "cost_center": cost_center or ""},
                                    {"account": credit_account, "credit_in_account_currency": float(doc.custom_activity_cost), "cost_center": cost_center or ""},
                                ],
                            })
                            je.insert(ignore_permissions=True)
                            je.submit()
                            frappe.db.set_value("Animal Event", doc.name, "custom_journal_entry", je.name, update_modified=False)
                            frappe.msgprint("JE " + str(je.name) + " created: KES " + str(doc.custom_activity_cost), indicator="green")
    except Exception as e:
        frappe.log_error(message=str(e), title="Livestock Auto JE Error")
        frappe.msgprint("JE failed: " + str(e), indicator="red")
